import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, Router } from '@angular/router';
import { ProjectService } from '../../../core/services/project.service';
import { AuthService } from '../../../core/services/auth.service';
import { DashboardStats, Project } from '../../../shared/models/models';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent implements OnInit {
  stats: DashboardStats | null = null;
  recentProjects: Project[] = [];
  loading = true;

  constructor(
    private projectService: ProjectService,
    public authService: AuthService,
    private router: Router
  ) {}

  ngOnInit() {
    this.loadData();
  }

  loadData() {
    this.loading = true;
    this.projectService.getDashboard().subscribe({
      next: (stats) => { this.stats = stats; },
      error: () => {}
    });
    this.projectService.getMy().subscribe({
      next: (projects) => {
        this.recentProjects = projects.slice(0, 5);
        this.loading = false;
      },
      error: () => { this.loading = false; }
    });
  }

  logout() {
    this.authService.logout();
    this.router.navigate(['/auth/login']);
  }

  getInitials(name: string): string {
    return name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
  }

  getBarWidth(count: number): string {
    if (!this.stats?.categoryStats?.length) return '0%';
    const max = Math.max(...this.stats.categoryStats.map(c => c.count));
    return max > 0 ? `${(count / max) * 100}%` : '0%';
  }
}
